async function cadastrarLivro(livro) {
    const sql = `
        INSERT INTO livros (titulo, autor_id, ano_publicacao, preco)
        VALUES (?, ?, ?, ?)
    `;

    const valores = [livro.titulo, livro.autor_id, livro.ano_publicacao, livro.preco];

    const [resultado] = await db.execute(sql, valores);

    return { id: resultado.insertId, ...livro };
}

async function atualizarLivro(id, dados) {
    const sql = `
        UPDATE livros
        SET titulo = ?, preco = ?
        WHERE id = ?
    `;

    const [resultado] = await db.execute(sql, [dados.titulo, dados.preco, id]);

    return resultado.affectedRows > 0;
}

if (resultado.affectedRows === 0) {
    console.log("Nenhum livro encontrado com esse id.");
}

async function removerLivro(id) {
    const [resultado] = await db.execute(
        "DELETE FROM livros WHERE id = ?",
        [id]
    );

    return resultado.affectedRows > 0;
}

async function removerLivro(id) {
    const [resultado] = await db.execute(
        "UPDATE livros SET ativo = FALSE WHERE id = ?",
        [id]
    );
    return resultado.affectedRows > 0;
}

