const db = require("../config/db");

async function listarTodos() {
    const [rows] = await db.query("SELECT * FROM livros");
    return rows;
}

async function buscarPorId(id) {
    const [rows] = await db.execute("SELECT * FROM livros WHERE id = ?", [id]);
    return rows[0];
}

async function inserir(livro) {
    const sql = "INSERT INTO livros (titulo, autor_id, preco) VALUES (?, ?, ?)";
    const [resultado] = await db.execute(sql, [livro.titulo, livro.autor_id, livro.preco]);
    return { id: resultado.insertId, ...livro };
}

module.exports = { listarTodos, buscarPorId, inserir };

